results.content:
{
  "returncode": 0,
  "output": "<header class="admin-header">
  <span class="logo"><span class="logo__mark">?</span>Quizzy</span>
  <span class="admin-header__tag">Moderator</span>
</header>

<main class="admin-main">
  <div class="breadcrumbs"><%= link_to "← All quizzes", moderate_root_path %></div>
  <div class="page-head">
    <div>
      <h1><%= @quiz.title %></h1>
      <div class="meta mt-2">
        <% active_count = @questions.count(&:active?) %>
        <%= active_count %> of <%= @questions.size %> questions active · <%= link_to "Settings", edit_moderate_quiz_path(@quiz) %>
      </div>
    </div>
    <div class="buttons"><%= link_to "Preview", preview_moderate_quiz_path(@quiz), class: "btn btn--ghost" %> <%= link_to "Export", export_moderate_quiz_path(@quiz), class: "btn btn--ghost" %></div>
  </div>

  <section class="section mt-0">
    <div class="section-head">
      <h2>Questions</h2>
      <%= link_to "Add question", new_moderate_quiz_question_path(@quiz), class: "btn" %>
    </div>

    <% if @questions.any? %>
      <ol class="question-list" style="list-style:none; padding:0; margin:0; display:flex; flex-direction:column; gap:16px;">
        <% @questions.each_with_index do |q, idx| %>
          <li class="card question-item <%= "question-item--inactive" unless q.active? %>">
            <div class="question-item__num"><%= q.active? ? (idx + 1) : "—" %></div>
            <div>
              <div class="question-item__body"><%= q.body %></div>
              <ul class="question-item__options">
                <% q.options.each_with_index do |opt, oi| %>
                  <% letter = ("A".ord + oi).chr %>
                  <li class="<%= "is-correct" if opt.correct? %>"><%= letter %>. <%= opt.text %></li>
                <% end %>
              </ul>
            </div>
            <div class="question-item__actions">
              <div class="buttons">
                <%= button_to "Move up", move_up_moderate_quiz_question_path(@quiz, q), method: :post, class: "btn btn--ghost btn--sm", form: { style: "display:inline" } %>
                <%= button_to "Move down", move_down_moderate_quiz_question_path(@quiz, q), method: :post, class: "btn btn--ghost btn--sm", form: { style: "display:inline" } %>
              </div>
              <%= form_with url: toggle_active_moderate_quiz_question_path(@quiz, q), method: :patch, local: true, html: { style: "display:inline" } do %>
                <span class="checkbox">
                  <input type="checkbox" name="question[active]" value="1" id="question_active_<%= q.id %>" <%= "checked" if q.active? %> onchange="this.form.submit()">
                  <label for="question_active_<%= q.id %>">Active</label>
                </span>
              <% end %>
              <div class="buttons">
                <%= link_to "Edit", edit_moderate_quiz_question_path(@quiz, q), class: "btn btn--sm" %>
                <%= button_to "Delete", moderate_quiz_question_path(@quiz, q), method: :delete, class: "btn btn--sm btn--danger", form: { onsubmit: "return confirm('Delete this question?')" } %>
              </div>
            </div>
          </li>
        <% end %>
      </ol>
    <% else %>
      <div class="empty">No questions yet. Add your first question.</div>
    <% end %>
  </section>
</main>
===INDEX===
<header class="admin-header">
  <span class="logo"><span class="logo__mark">?</span>Quizzy</span>
  <span class="admin-header__tag">Moderator</span>
</header>

<main class="admin-main">
  <div class="page-head">
    <div>
      <h1>Quizzes</h1>
    </div>
    <div class="buttons">
      <%= link_to "New quiz", new_moderate_quiz_path, class: "btn btn--pink" %>
      <%= link_to "Import quiz", moderate_import_path, class: "btn btn--ghost" %>
    </div>
  </div>

  <% if @quizzes.any? %>
    <ul class="quiz-list">
      <% @quizzes.each do |quiz| %>
        <li class="card quiz-tile">
          <h3><%= link_to quiz.title, moderate_quiz_path(quiz) %></h3>
          <div class="meta"><%= pluralize(quiz.questions.count, "question") %></div>
          <div class="buttons" style="margin-top: 12px;">
            <%= link_to "Preview", preview_moderate_quiz_path(quiz), class: "btn btn--sm btn--ghost" %>
            <%= link_to "Settings", edit_moderate_quiz_path(quiz), class: "btn btn--sm" %>
          </div>
        </li>
      <% end %>
    </ul>
  <% else %>
    <div class="empty">No quizzes yet. Create your first quiz to get started.</div>
  <% end %>
</main>
===LAYOUT===
