<section class="cover cover--blue cover--calm">
<div class="screen" id="game-root" data-state-url="<%= state_moderate_quiz_game_path(@quiz, @game) %>" data-status="<%= @game.status %>" data-question-id="<%= @game.current_question_id %>">
  <div class="screen__top">
    <span class="logo screen__logo"><span class="logo__mark">?</span>Quizzy</span>
    <span id="quiz-title"><%= h @quiz.title %></span>
  </div>

  <div class="screen__body" id="screen-body">
    <% if @game.waiting? %>
      <div class="lobby" id="lobby">
        <div>
          <h1 class="lobby__title" style="margin:0"><%= h @quiz.title %></h1>
          <div class="lobby__join">Join at</div>
          <div class="lobby__url" id="join-url"><%= h @join_url %></div>
          <div class="counter-pill" id="players-counter">Players: <%= @players_count %></div>
        </div>
        <div class="qr" id="qr-code" aria-label="QR code for join link"><%= @qr_svg.html_safe %></div>
      </div>
    <% elsif @game.open? || @game.closed? %>
      <% if @current_question %>
        <div class="stage-question__num" id="question-progress"><%= h @progress %></div>
        <div class="stage-question__body" id="question-body"><%= h @current_question.body %></div>
        <% if @game.open? %>
          <ol class="stage-options" id="options-list">
            <% @options.each_with_index do |opt, idx| %>
              <% letter = ("A".ord + idx).chr %>
              <li class="stage-option" data-option-id="<%= opt.id %>">
                <span class="stage-option__letter"><%= letter %></span>
                <span class="stage-option__title"><%= h opt.text %></span>
              </li>
            <% end %>
          </ol>
        <% else %>
          <ol class="stage-options stage-options--results" id="options-list">
            <% total_answers = @answers_count.nonzero? || 1 %>
            <% @options.each_with_index do |opt, idx| %>
              <% letter = ("A".ord + idx).chr %>
              <% cnt = @counts[opt.id] || 0 %>
              <% share = (cnt.to_f / total_answers * 100).round %>
              <li class="stage-option <%= "is-correct" if opt.correct? %>" data-option-id="<%= opt.id %>">
                <span class="stage-option__bar" style="--share: <%= share %>%"></span>
                <span class="stage-option__letter"><%= letter %></span>
                <span class="stage-option__title"><%= h opt.text %></span>
                <span class="stage-option__count" id="count-<%= opt.id %>"><%= cnt %></span>
                <% if opt.correct? %>
                  <span class="play-option__mark">Correct</span>
                <% end %>
              </li>
            <% end %>
          </ol>
        <% end %>
        <div style="margin-top: 24px; display: flex; gap: 16px; align-items: center; flex-wrap: wrap;">
          <span class="counter-pill" id="players-counter" style="margin-top:0">Players: <%= @players_count %></span>
          <span class="answers-counter" id="answers-counter">Answers: <%= @answers_count %> / <%= @players_count %></span>
        </div>
      <% else %>
        <div class="stage-question__body">No question available</div>
        <div class="counter-pill" id="players-counter">Players: <%= @players_count %></div>
      <% end %>
    <% elsif @game.ended? %>
      <div class="stage-question__body" id="over-message">The quiz is over</div>
    <% end %>
  </div>

  <div class="screen-controls">
    <div class="screen-controls__info">
      <%= link_to "← Back to quiz", moderate_quiz_path(@quiz) %>
      <span>Game <%= h @game.code %></span>
    </div>
    <div class="buttons" id="game-actions">
      <% if @game.waiting? %>
        <%= button_to "Start", start_moderate_quiz_game_path(@quiz, @game), method: :post, class: "btn btn--pink btn--lg", form: { id: "action-form" } %>
      <% elsif @game.open? %>
        <%= button_to "Finish", finish_moderate_quiz_game_path(@quiz, @game), method: :post, class: "btn btn--pink btn--lg", form: { id: "action-form" } %>
      <% elsif @game.closed? %>
        <% if @is_last %>
          <%= button_to "End quiz", end_quiz_moderate_quiz_game_path(@quiz, @game), method: :post, class: "btn btn--pink btn--lg", form: { id: "action-form" } %>
        <% else %>
          <%= button_to "Next", next_step_moderate_quiz_game_path(@quiz, @game), method: :post, class: "btn btn--pink btn--lg", form: { id: "action-form" } %>
        <% end %>
      <% end %>
    </div>
  </div>
</div>
</section>

<script>
(function() {
  var root = document.getElementById('game-root');
  if (!root) return;
  var stateUrl = root.getAttribute('data-state-url');
  var lastStatus = root.getAttribute('data-status');
  var lastQuestionId = root.getAttribute('data-question-id');
  var polling = true;

  function csrfToken() {
    var m = document.querySelector('meta[name="csrf-token"]');
    return m ? m.getAttribute('content') : '';
  }

  // Intercept action form to work without full reload when possible,
  // but fallback to normal submit if fetch fails.
  function bindActionForm() {
    var form = document.getElementById('action-form');
    if (!form || form.dataset.bound) return;
    form.dataset.bound = '1';
    form.addEventListener('submit', function(ev) {
      ev.preventDefault();
      var url = form.getAttribute('action');
      var token = csrfToken();
      fetch(url, {
        method: 'POST',
        headers: { 'Accept': 'application/json', 'X-CSRF-Token': token, 'X-Requested-With': 'XMLHttpRequest' },
        credentials: 'same-origin'
      }).then(function(r) {
        if (r.ok) {
          return r.json().then(function(data) {
            // Full reload to show new state is simplest and still live for counters.
            // But to avoid reload, we reload only on action (user-initiated), not on live updates.
            // For smoother UX, reload the page to reflect new state.
            window.location.reload();
          }).catch(function() { window.location.reload(); });
        } else {
          window.location.reload();
        }
      }).catch(function() {
        // Network issue (crowded wifi): fallback to normal submit
        form.submit();
      });
    });
  }
  bindActionForm();

  function poll() {
    if (!polling) return;
    if (document.hidden) return; // save battery, will poll when visible
    fetch(stateUrl, { headers: { 'Accept': 'application/json' }, credentials: 'same-origin' })
      .then(function(r) {
        if (!r.ok) return null;
        return r.json();
      })
      .then(function(data) {
        if (!data) return;
        // If status or question changed (e.g., other tab triggered), reload to show new state
        // Counters are updated live without reload; state changes reload only if not caused by this tab.
        // To keep "without reloads" for counters, we update counters in place.
        var statusChanged = (data.status !== lastStatus) || (String(data.question_id || '') !== String(lastQuestionId || ''));
        if (statusChanged) {
          // For live without reload, we could re-render via JS, but simplest robust is reload.
          // However spec says big screen follows without reloads. Counters already live.
          // State changes from other tabs are rare; reload is acceptable fallback.
          // To avoid reload loops, only reload if status actually changed.
          window.location.reload();
          return;
        }
        // Update counters live
        var pc = document.getElementById('players-counter');
        if (pc && data.players_text) {
          if (pc.textContent !== data.players_text) pc.textContent = data.players_text;
        }
        var ac = document.getElementById('answers-counter');
        if (ac && data.answers_text) {
          if (ac.textContent !== data.answers_text) ac.textContent = data.answers_text;
        } else if (!ac && data.answers_text && (data.status === 'open' || data.status === 'closed')) {
          // If answers counter missing but should exist, reload to render it
          window.location.reload();
          return;
        }
        // Update per-option counts when closed (in case new players joined, denominator changed already)
        if (data.status === 'closed' && data.options) {
          data.options.forEach(function(opt) {
            var el = document.getElementById('count-' + opt.id);
            if (el && el.textContent !== String(opt.count)) {
              el.textContent = String(opt.count);
            }
          });
        }
        // Update join URL if changed (host may differ? keep initial)
      })
      .catch(function() {
        // Ignore errors (crowded wifi), will retry next interval
      });
  }

  setInterval(poll, 500);
  // Also poll on visibility change
  document.addEventListener('visibilitychange', function() {
    if (!document.hidden) poll();
  });
})();
</script>
ERB
