(function() {
  var root = document.getElementById('play-root');
  if (!root) return;
  var stateUrl = root.getAttribute('data-state-url');
  var answerUrl = root.getAttribute('data-answer-url');
  var lastSig = '';
  var busy = false;

  function csrfToken() {
    var m = document.querySelector('meta[name="csrf-token"]');
    return m ? m.getAttribute('content') : '';
  }

  function esc(s) {
    return String(s == null ? '' : s);
  }

  function show(el) { if (el) el.style.display = ''; }
  function hide(el) { if (el) el.style.display = 'none'; }

  function renderOptions(container, opts, canPick) {
    if (!container) return;
    // Clear
    while (container.firstChild) container.removeChild(container.firstChild);
    for (var i = 0; i < opts.length; i++) {
      (function(opt) {
        var letter = opt.letter || String.fromCharCode(65 + i);
        if (canPick) {
          var f = document.createElement('form');
          f.method = 'post';
          f.action = answerUrl;
          f.setAttribute('data-opt-form', '1');
          var tok = document.createElement('input');
          tok.type = 'hidden';
          tok.name = 'authenticity_token';
          tok.value = csrfToken();
          f.appendChild(tok);
          var hid = document.createElement('input');
          hid.type = 'hidden';
          hid.name = 'option_id';
          hid.value = opt.id;
          f.appendChild(hid);
          var b = document.createElement('button');
          b.type = 'submit';
          b.className = 'play-option' + (opt.picked ? ' is-picked' : '');
          b.setAttribute('data-option-id', opt.id);
          var ls = document.createElement('span');
          ls.className = 'play-option__letter';
          ls.textContent = letter;
          b.appendChild(ls);
          var ts = document.createElement('span');
          ts.className = 'play-option__title';
          ts.textContent = esc(opt.text);
          b.appendChild(ts);
          if (opt.picked) {
            var mk = document.createElement('span');
            mk.className = 'play-option__mark';
            mk.textContent = 'Your answer';
            b.appendChild(mk);
          }
          f.appendChild(b);
          // intercept
          f.addEventListener('submit', function(ev) {
            ev.preventDefault();
            sendPick(opt.id);
          });
          container.appendChild(f);
        } else {
          var d = document.createElement('div');
          d.className = 'play-option' + (opt.picked ? ' is-picked' : '');
          d.setAttribute('data-option-id', opt.id);
          var l2 = document.createElement('span');
          l2.className = 'play-option__letter';
          l2.textContent = letter;
          d.appendChild(l2);
          var t2 = document.createElement('span');
          t2.className = 'play-option__title';
          t2.textContent = esc(opt.text);
          d.appendChild(t2);
          if (opt.picked) {
            var m2 = document.createElement('span');
            m2.className = 'play-option__mark';
            m2.textContent = 'Your answer';
            d.appendChild(m2);
          }
          container.appendChild(d);
        }
      })(opts[i]);
    }
  }

  function sendPick(optId) {
    if (busy) return;
    busy = true;
    var token = csrfToken();
    var body = 'option_id=' + encodeURIComponent(optId) + '&authenticity_token=' + encodeURIComponent(token);
    fetch(answerUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8', 'Accept': 'application/json', 'X-CSRF-Token': token, 'X-Requested-With': 'XMLHttpRequest' },
      credentials: 'same-origin',
      body: body
    }).then(function(r) {
      busy = false;
      if (r.ok) {
        return r.json().then(function(d) { applyState(d); }).catch(function() { pollSoon(); });
      } else {
        pollSoon();
      }
    }).catch(function() { busy = false; });
  }

  function applyState(d) {
    if (!d) return;
    var sig = (d.game_status || '') + '|' + (d.question_id || '') + '|' + (d.result_text || '') + '|' + d.options.length + '|';
    // include picked ids in sig
    for (var i = 0; i < d.options.length; i++) {
      if (d.options[i].picked) sig += d.options[i].id + ',';
    }
    sig += '|' + (d.progress || '') + '|' + (d.question_body || '').length;
    var greetingEl = document.getElementById('greeting');
    var waitingEl = document.getElementById('waiting-section');
    var qSection = document.getElementById('question-section');
    var qNum = document.getElementById('question-progress');
    var qBody = document.getElementById('question-body');
    var optsBox = document.getElementById('options');
    var resEl = document.getElementById('result');
    var overEl = document.getElementById('over-section');

    if (d.is_over || d.game_status === 'ended') {
      hide(waitingEl); hide(qSection); show(overEl);
      if (greetingEl && d.greeting) greetingEl.textContent = d.greeting;
      lastSig = sig;
      return;
    }
    hide(overEl);
    if (greetingEl && d.greeting) {
      if (greetingEl.textContent !== d.greeting) greetingEl.textContent = d.greeting;
    }
    if (d.game_status === 'waiting') {
      show(waitingEl); hide(qSection); hide(overEl);
      if (resEl) hide(resEl);
      lastSig = sig;
      return;
    }
    // open or closed: show question
    hide(waitingEl); show(qSection); hide(overEl);
    if (qNum) {
      var pt = d.progress || '';
      if (qNum.textContent !== pt) qNum.textContent = pt;
    }
    if (qBody) {
      var qb = d.question_body || '';
      if (qBody.textContent !== qb) qBody.textContent = qb;
    }
    // options: re-render if sig changed or count differs
    if (sig !== lastSig) {
      var canPick = !!d.can_answer;
      renderOptions(optsBox, d.options || [], canPick);
      if (resEl) {
        if (d.result_text) {
          resEl.textContent = d.result_text;
          resEl.className = 'play-status ' + (d.result_class || '');
          show(resEl);
        } else {
          resEl.textContent = '';
          hide(resEl);
        }
      }
    } else {
      // Even if sig same, ensure result visibility matches
      if (resEl) {
        if (d.result_text) {
          if (resEl.textContent !== d.result_text) resEl.textContent = d.result_text;
          var wantCls = 'play-status ' + (d.result_class || '');
          if (resEl.className !== wantCls) resEl.className = wantCls;
          show(resEl);
        } else {
          hide(resEl);
        }
      }
    }
    lastSig = sig;
  }

  var timer = null;
  function pollSoon() {
    if (timer) return;
    timer = setTimeout(function() { timer = null; poll(); }, 200);
  }

  function poll() {
    if (document.hidden) return;
    if (busy) return;
    fetch(stateUrl, { headers: { 'Accept': 'application/json' }, credentials: 'same-origin' })
      .then(function(r) { if (!r.ok) return null; return r.json(); })
      .then(function(d) { if (d) applyState(d); })
      .catch(function() {});
  }

  // Bind existing forms (server-rendered) for instant pick without reload
  function bindExisting() {
    var forms = document.querySelectorAll('form[data-opt-form]');
    for (var i = 0; i < forms.length; i++) {
      (function(f) {
        if (f.dataset.bound) return;
        f.dataset.bound = '1';
        f.addEventListener('submit', function(ev) {
          ev.preventDefault();
          var hid = f.querySelector('input[name="option_id"]');
          var oid = hid ? hid.value : null;
          if (oid) sendPick(oid);
        });
      })(forms[i]);
    }
  }
  bindExisting();

  setInterval(poll, 500);
  document.addEventListener('visibilitychange', function() { if (!document.hidden) poll(); });
  // initial poll soon to sync
  setTimeout(poll, 300);
})();
